def parse_chain(path):
    chains=[]; hdr=None; toks=[]
    def finish(hdr,toks):
        blocks=[]; i=0
        while i < len(toks):
            if len(toks)-i == 1: blocks.append((toks[i],0,0)); i+=1
            elif len(toks)-i == 2: raise ValueError('bad chain block tokens: %r'%(toks,))
            else: blocks.append((toks[i],toks[i+1],toks[i+2])); i+=3
        return dict(score=hdr[10], id=hdr[11],
                    t=dict(name=hdr[0],size=hdr[1],strand=hdr[2],start=hdr[3],end=hdr[4]),
                    q=dict(name=hdr[5],size=hdr[6],strand=hdr[7],start=hdr[8],end=hdr[9]),
                    blocks=blocks)
    out=[]
    for line in open(path):
        p=line.split()
        if not p:
            if hdr is not None: out.append(finish(hdr,toks)); hdr=None; toks=[]
            continue
        if p[0]=='chain':
            if hdr is not None: out.append(finish(hdr,toks))
            hdr=[p[2],int(p[3]),p[4],int(p[5]),int(p[6]),p[7],int(p[8]),p[9],int(p[10]),int(p[11]),int(p[1]),int(p[12])]
            toks=[]
        else:
            toks.extend(int(x) for x in p)
    if hdr is not None: out.append(finish(hdr,toks))
    for c in out:
        assert c['t']['strand']=='+', 'target strand must be +'
    return out

def block_spans(c, convention):
    """return list of (tstart, tsize, qstart, strand) where qstart is the query-coordinate
    interval start [qstart, qstart+size) that the target block aligns to."""
    spans=[]
    tp=c['t']['start']
    if c['q']['strand']=='+':
        qp=c['q']['start']
        for size,tg,qg in c['blocks']:
            spans.append((tp,size,qp,'+'))
            tp+=size+tg; qp+=size+qg
    else:
        if convention=='fwd':      # query pointer advances forward from qStart
            qp=c['q']['start']
            for size,tg,qg in c['blocks']:
                spans.append((tp,size,qp,'-'))
                tp+=size+tg; qp+=size+qg
        else:                       # UCSC style: blocks occupy query span read backwards from qEnd
            qe=c['q']['end']
            for size,tg,qg in c['blocks']:
                qe-=qg
                spans.append((tp,size,qe-size,'-'))
                tp+=size+tg; qe-=size
    return spans
