import sys; sys.path.insert(0,'/task/work')
import numpy as np, collections
from chain import parse_chain
from lib import load_fasta

RC = bytes.maketrans(b'ACGTNacgtn', b'TGCANtgcan')

def chain_blocks(path):
    """return list of tuples (tstart, tsize, qstart, qstep) qstep=+1/-1"""
    out=[]
    for c in parse_chain(path):
        tp=c['t']['start']
        if c['q']['strand']=='+':
            qp=c['q']['start']
            for size,tg,qg in c['blocks']:
                out.append((tp,size,qp,1,c['score']))
                tp+=size+tg; qp+=size+qg
        else:
            qe=c['q']['end']
            for size,tg,qg in c['blocks']:
                qe-=qg
                out.append((tp,size,qe-size,-1,c['score']))
                tp+=size+tg; qe-=size
    return out

def hg19_to_hg38(pos0, blks):
    """pos0: 0-based hg19 coordinate; return list of (hg38_0based, strand)"""
    res=[]
    for (ts,size,qs,st,score) in blks:
        if ts <= pos0 < ts+size:
            k=pos0-ts
            res.append((qs+k if st>0 else qs+size-1-k, st))
    return res

def hg38_to_hg19(pos0, blks):
    res=[]
    for (ts,size,qs,st,score) in blks:
        if qs <= pos0 < qs+size:
            k=pos0-qs
            if st>0: res.append((ts+k, st))
            else: res.append((ts+size-1-k, st))
    return res

def n_intervals(arr):
    idx=np.where(arr==b'N')[0]
    if len(idx)==0: return []
    br=np.where(np.diff(idx)>1)[0]
    st=np.r_[idx[0], idx[br+1]]; en=np.r_[idx[br], idx[-1]]
    return [(int(a),int(b)) for a,b in zip(st,en)]

def invert_intervals(ivs, length):
    out=[]; cur=0
    for a,b in ivs:
        if a>cur: out.append((cur,a-1))
        cur=max(cur,b+1)
    if cur<length: out.append((cur,length-1))
    return out
